/* R5 is an isolated interaction prototype. It makes no HTTP/model requests. */
(() => {
  'use strict';
  const M=window.R5Math, KEY='luojia-r5-prototype-v1';
  const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=(x,n=6)=>x==null?'—':Number.isFinite(x)?Number(x.toPrecision(n)).toString():'未确定';
  const seed=[
    {id:'seed-error',type:'error',concept:'残差与根误差',title:'残差很小，就一定离根很近吗？',text:'演示错误主张：残差 10⁻¹²，因此根误差也小于 10⁻¹²。',evidence:'取 f(x)=10⁻¹²(x−1)，在 x=0 处残差是 10⁻¹²，唯一根为 1，根误差为 1。缺少把残差转换为误差的导数下界。',source:'公开教学反例 · 原型样例 v1',help:'演示纠错，未独立检验',action:'learn'},
    {id:'seed-reading',type:'reading',concept:'Newton 的适用条件',title:'局部收敛，不等于任意初值收敛',text:'演示阅读笔记：核对可微性、简单根和初值邻域；不满足一个充分条件，也不能直接推出发散。',evidence:'这是整理后的教学说明，不是教材原文或已签署审核结果。正式原文应通过既有 Reading 来源引用读取。',source:'原型教学说明 v1 · 待独立审核',help:'参考阅读',action:'learn'},
    {id:'seed-note',type:'note',concept:'Gauss–Seidel',title:'后一个分量用本轮的新值',text:'演示笔记：逐行更新时，第二行应该使用刚求出的第一个分量。',evidence:'矩阵 [[4,1],[2,3]]、b=[1,2]、x⁽⁰⁾=[0,0] 时，第一轮得到 [1/4,1/2]。',source:'可复算教学样例 · 原型 v1',help:'有参考帮助',action:'experiment',domain:'gs'}
  ];
  const defaults=()=>({version:1,taskDraft:{prediction:'',revised:''},dialogue:{sessions:[],selected:null,draft:''},homeQuestion:'',stage:0,unlocked:0,conditions:false,prediction:'',predictionChoice:'',judgment:'',claim:'',revised:'',runId:null,reviseId:null,observed:false,feedback:false,probe:{active:false,help:false,answer:'',passed:false,submitted:false,attempts:0},runs:[],records:structuredClone(seed),review:[],domain:'newton',layout:'B',selectedRun:null,step:0,compare:null,question:'',chat:[],filter:'all',search:'',selectedRecord:'seed-error',drafts:{newton:{function:'cycle',x0:'1',limit:'8',tolerance:'0.0000001'},gs:{matrix:'4 1; 2 3',rhs:'1 2',initial:'0 0',limit:'8',tolerance:'0.0000001'},integration:{left:'0',right:'1',intervals:'8',method:'simpson'}}});
  let storageOK=true,S=defaults();
  try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw?.version===1&&Array.isArray(raw.runs)&&Array.isArray(raw.records))S={...S,...raw,probe:{...S.probe,...raw.probe},drafts:{...S.drafts,...raw.drafts}};if(!raw?.taskDraft)S.taskDraft={prediction:S.taskPrediction||'',revised:S.records.find(r=>r.type==='revision'&&r.runId===S.reviseId)?.text||''};}catch{storageOK=false;}
  S.dialogue={sessions:[],selected:null,draft:'',materials:[],materialTitle:'',materialText:'',...S.dialogue};
  let route='home',error='',toastTimer,materialSelection=null;
  const steps=['选择任务','必要条件','作出预测','观察实验','提交判断','修订主张','独立检验','学习回看'];
  const names={newton:'Newton 求根',gs:'Gauss–Seidel',integration:'数值积分'};
  const statuses={cycle:'检测到二周期',residual_stop:'达到残差阈值',derivative_zero:'导数近零，停止',budget:'达到步数上限',non_finite:'数值超出预算',quadrature:'已完成参考求积'};
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S));}catch{storageOK=false;}};
  const announce=text=>{document.getElementById('announcement').textContent=text;};
  function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=text;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500);}
  function addRecord(record){S.records.unshift({id:'record-'+Date.now()+'-'+S.records.length,...record});save();}
  function addRun(domain,p,prediction=S.prediction){const run={...({newton:M.newton,gs:M.gs,integration:M.integrate}[domain])(p),id:'r5-run-'+(S.runs.length+1),version:S.runs.length+1,prediction,created:new Date().toISOString()};run.input_hash=M.hash(run.parameters);S.runs.push(run);S.selectedRun=run.id;S.domain=domain;S.step=0;S.compare=null;save();return run;}
  const getRun=id=>S.runs.find(r=>r.id===id);
  const activeRun=()=>getRun(S.selectedRun)||S.runs.filter(r=>r.domain===S.domain).at(-1);
  const contextRun=()=>route==='learn'&&S.reviewOrigin?null:route==='learn'?getRun(S.stage===5?S.reviseId:S.runId):route==='experiment'?activeRun():route==='records'?getRun(S.records.find(x=>x.id===S.selectedRecord)?.runId):null;
  const contextKey=(r=contextRun())=>r?.id||(route==='learn'?(S.reviewOrigin?'review:'+S.reviewOrigin:'task:newton'):route==='records'?'record:'+S.selectedRecord:route==='experiment'?'experiment:'+S.domain:'home');
  const contextLabel=()=>route==='learn'&&S.reviewOrigin?'当前复习：残差与根误差。来源 '+S.reviewOrigin+'；新题 g(x)=10⁻⁸(x−2)，候选 x=0。':route==='records'?'当前学习记录：'+(S.records.find(x=>x.id===S.selectedRecord)?.title||'尚未选中记录')+'。尚未绑定计算快照。':route==='learn'?'当前任务：Newton 的局部与整体。还没有选中计算记录。':route==='experiment'?'当前实验：'+names[S.domain]+'。尚未保存计算快照，请先写预测并运行。':'当前学习中心：先选择任务或实验，再围绕具体来源讨论。';
  const locked=()=>Boolean(S.probe.active&&!S.probe.passed&&!S.probe.help||S.reviewAttempt?.active&&!S.reviewAttempt.passed&&!S.reviewAttempt.help);
  function next(stage){S.stage=stage;S.unlocked=Math.max(S.unlocked,stage);error='';save();render(true);}
  function parseRoute(){const url=new URL(location.href);const raw=url.hash.slice(1).split('?')[0];route=['home','chat','learn','experiment','records'].includes(raw)?raw:'home';if(raw==='learn'&&new URLSearchParams(url.hash.split('?')[1]||'').get('task')==='newton'){S.reviewOrigin=null;if(S.reviewAttempt)S.reviewAttempt.active=false;save();}if(raw==='experiment'){const params=new URLSearchParams(url.hash.split('?')[1]||'');const layout=params.get('layout');if(['A','B'].includes(layout))S.layout=layout;}render(true);}
  const link=(target,label,cls='btn secondary')=>`<a class="${cls}" href="#${target}">${label}</a>`;
  const button=(action,label,cls='btn secondary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
  function heading(kicker,title,desc){return `<div class="heading"><div><div class="eyebrow">${kicker}</div><h1 tabindex="-1">${title}</h1><p>${desc}</p></div><span class="tag neutral">交互原型 · R5</span></div>`;}
  function shell(content){return `<div class="frame"><aside class="rail"><a href="#home" class="brand"><img src="assets/luojia-logo.png" alt="珞珈数智 Logo"><span>珞珈数智<small>数 值 研 习 册</small></span></a><nav aria-label="原型主导航">${[['home','⌂','学习中心'],['chat','◇','自由对话'],['learn','∂','学习工作区'],['experiment','ƒ','数学实验'],['records','≡','学习记录']].map(([key,icon,label])=>`<a href="#${key}" ${route===key?'aria-current="page"':''}><span class="navmark" aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav><div class="rail-foot"><p>数值分析<br>条件 · 过程 · 独立判断</p><details><summary>原型说明与演示设置</summary><p>计算在浏览器中执行。记录仅属于此原型；小珞使用明确标记的规则示例。</p>${button('empty-records','体验空记录','')}${button('reset','重置原型演示','')}<a class="text-link" href="review.md">查看设计取舍</a></details></div></aside><div class="appbody"><header class="top"><div class="location">数值分析 <span aria-hidden="true"> / </span> ${ {home:'由你选择今天的开始',chat:'与小珞自由对话',learn:S.reviewOrigin?'残差与根误差 · 复习任务':'Newton · 一项完整任务',experiment:'观察与解释',records:'从记录回到学习'}[route]}</div><div class="top-right"><span class="prototype-label">演示数据<br>不连接真实账号</span><button class="tutor-trigger" data-action="open-tutor"><img src="assets/xiaoluo.png" alt=""><span>问小珞</span></button></div></header>${!storageOK?'<p class="storage-notice" role="status">浏览器存储不可用，本次仍可体验；关闭页面后演示草稿可能丢失。</p>':''}<main class="page" id="main" tabindex="-1">${content}<footer class="footer-note">R5 独立原型 · 示例资料与浏览器浮点计算，非真实学生档案。小珞使用规则化示例反馈，未调用模型。<br>所有演示更改仅保存在当前浏览器的原型空间；正式 UI、账号和数据库保持独立。</footer></main></div></div><dialog class="tutor-drawer" id="tutor-dialog" aria-label="小珞上下文讨论"><div class="drawer-close">${button('close-tutor','关闭讨论','')}</div><div id="drawer-content"></div></dialog>`;}
  function home(){const progress=S.stage===7?'回看本次学习':steps[S.stage];return heading('珞珈数智 · 数学助教','今天，想先聊什么？','直接讨论概念、推导或解题思路，也可以继续一项学习任务。')+homeDialogue()+`<section class="home-hero" aria-label="当前学习任务"><div class="hero-copy"><span class="tag">Newton 法 · 局部与整体</span><h2>一步算对了，<br>就一定会收敛吗？</h2><p>从 x₀ = 1 出发。先读条件、预测轨迹，再用一次对照实验修订自己的判断。</p><div class="actions">${link('learn?task=newton',S.stage?'继续：'+progress:'开始这项学习','btn')}${button('go-gs','直接探索 GS','btn quiet')}</div><ol class="path-list">${['读条件','先预测','做实验','改判断','独立检验'].map((x,i)=>`<li class="${S.unlocked>i+1?'done':''}"><i></i>${x}</li>`).join('')}</ol></div><div class="hero-math"><p class="small muted">${S.observed?'回看你已观察的轨迹':'先预测，再揭开轨迹'}</p><p class="formula">f(x) = x³ − 2x + 2</p><div class="orbit" aria-label="${S.observed?'已观察的二周期':'尚未揭示的迭代轨迹'}"><b>1</b><span>→</span><b>${S.observed?'0':'?'}</b><span>${S.observed?'↺':'→ ?'}</span></div><p class="small muted">${S.observed?'这条指定初值的运行出现二周期。':'第一个新点，会落在哪里？'}<br>“这一轮可算”与“最后会收敛”是两个判断。</p></div></section><div class="home-lower"><section><div class="section-head"><h2>最近的学习线索</h2>${link('records','查看全部','text-link')}</div>${S.records.slice(0,3).map(r=>`<a class="entry" href="#records" data-record="${h(r.id)}"><span class="entry-icon">${{error:'?',reading:'文',experiment:'ƒ',probe:'✓',note:'记'}[r.type]||'记'}</span><div class="entry-main"><h3>${h(r.title)}</h3><p>${h(r.concept)} · ${h(r.help)}</p></div><span aria-hidden="true">↗</span></a>`).join('')||'<p class="empty">还没有演示记录，从当前任务开始。</p>'}</section><section><div class="section-head"><h2>换一种方式探索</h2></div>${[['go-newton','Newton 求根','观察初值如何改变轨迹。'],['go-gs','线性方程组','逐行看 Gauss–Seidel 的新分量。'],['go-integration','数值积分','比较加密网格后的参考求积。']].map(([act,title,desc])=>`<button class="entry" style="width:100%;background:none;border-left:0;border-right:0;border-bottom:0;text-align:left" data-action="${act}"><div class="entry-main"><h3>${title}</h3><p>${desc}</p></div><span>→</span></button>`).join('')}</section></div>`;}
  function ledger(){return `<aside class="ledger" aria-label="判断账页"><span class="small muted">这条学习路径一直保留</span><h3>我的判断账页</h3><dl><dt>我原先认为</dt><dd>${h(S.taskPrediction||getRun(S.runId)?.prediction||S.taskDraft.prediction||'还没有预测。写下自己的理由，比选对答案更重要。')}</dd><dt>实验观察</dt><dd>${getRun(S.runId)?'x₀=1：1 → 0 → 1，出现二周期。':'尚未运行本任务。'}</dd><dt>我现在主张</dt><dd>${h(S.taskDraft.revised||S.judgment||'等待你的判断与修订。')}</dd></dl><div class="context"><span class="tag ${S.probe.help?'warn':''}">${S.probe.passed?(S.probe.help?'借助帮助完成':'独立数值检查通过'):S.probe.active?'独立检验进行中':'参考学习阶段'}</span><p class="small muted" style="margin-top:10px">这里记录的是过程，不推断你已掌握整个方法。</p></div></aside>`;}
  const radio=(name,value,label,selected)=>`<label class="choice"><input type="radio" name="${name}" value="${value}" ${selected===value?'checked':''}>${label}</label>`;

  function reviewLearning(){const a=S.reviewAttempt;const source=S.records.find(r=>r.id===S.reviewOrigin)||seed[0];return heading('从错误回到学习','残差与根误差：换个问题再判断。','来源：'+source.title+'。当前题是新的数值检查；文字理由不自动评分。')+`<div class="workspace"><section class="panel"><span class="tag ${a.help?'warn':''}">${a.help?'借助参考复习':'新题独立数值尝试'}</span><h2 class="lesson-title" style="margin-top:18px">把两个量分别算出来</h2><div class="formula-box">g(x) = 10⁻⁸(x − 2)，候选 x = 0<br>残差为 10⁻⁸ × 2，根误差是多少？</div><label class="field">我的根误差<input data-bind="reviewAttempt.answer" inputmode="decimal" value="${h(a.answer)}" placeholder="输入数值"></label><label class="field">为什么小残差还需要额外条件？<textarea data-bind="reviewAttempt.reason" maxlength="1200">${h(a.reason)}</textarea></label><div class="actions">${button('review-submit','核对本题数值候选','btn')}${button('review-help','查看参考（保留帮助标签）','btn secondary')}</div>${a.help?'<div class="callout neutral">本题唯一根为 2，所以根误差 |0−2|=2。将残差转换为误差需要函数的尺度或导数下界等额外信息。</div>':''}${a.submitted?`<div class="callout ${a.passed?'':'warn'}">${a.passed?'数值候选匹配；你的文字理由尚未自动核验。':'数值候选不匹配，输入已保留。'} ${a.help?'本次记为借助帮助。':'本次保留独立尝试标签。'}</div>`:''}${error?`<p role="alert" class="error">${h(error)}</p>`:''}<div class="rule actions">${link('records','回看来源与本次记录','btn secondary')}${button('review-exit','返回 Newton 主任务','btn quiet')}</div></section><aside class="ledger"><h3>这次复习的来源</h3><p class="small" style="margin-top:15px">${h(source.text)}</p><div class="context"><span class="small muted">${h(source.source)}</span><p class="small" style="margin-top:12px">原错误、参考依据和本次新题分别保存。数值匹配不等于已掌握误差理论。</p></div></aside></div>`;}
  function learn(){if(S.reviewOrigin&&S.reviewAttempt)return reviewLearning();let body='';const st=S.stage;
    if(st===0)body=`<h2 class="lesson-title">今天要回答一个具体问题</h2><p class="lesson-copy">“只要每一步的导数不为零，Newton 法就能收敛。”这个说法缺少什么？先以 f(x)=x³−2x+2 为对象，检查 x₀=1 的运行。</p><div class="formula-box">xₖ₊₁ = xₖ − f(xₖ) / f′(xₖ)</div><p class="small muted">预计 10–15 分钟 · 包含参考帮助阶段和一道新的独立数值题。教材条件说明为原型整理内容，不冒充教材原文。</p><div class="actions">${button('next','查看必要条件','btn')}</div>`;
    if(st===1)body=`<h2 class="lesson-title">把“能算”与“会收敛”分开</h2><div class="lesson-copy"><p>在某一步 f′(xₖ) ≠ 0，只能说明这一步的更新式有定义。</p><p>常见的局部收敛充分条件还涉及：根附近的光滑性、简单根，以及初值在适当邻域内。满足这些条件可以支持局部结论；没有满足某个充分条件，不能直接断言发散。</p><ul><li>这道题：f′(x) = 3x² − 2。</li><li>我们只观测指定初值，不把有限轨迹当作全称证明。</li></ul></div><label class="choice"><input type="checkbox" id="conditions" ${S.conditions?'checked':''}>我将分别检查“当前一步可算”和“整体收敛”</label><div class="actions">${button('next','写下我的预测','btn')}</div>`;
    if(st===2)body=`<h2 class="lesson-title">运行之前，你认为会发生什么？</h2><p class="lesson-copy">f(x)=x³−2x+2，初值 x₀=1。先作预测，再给出一个理由。</p><fieldset class="choices" style="border:0;padding:0"><legend class="sr-only">轨迹预测</legend>${radio('predictionChoice','converge','会趋近某个根',S.predictionChoice)}${radio('predictionChoice','cycle','可能进入重复轨迹',S.predictionChoice)}${radio('predictionChoice','unknown','现有条件还不足以判断',S.predictionChoice)}</fieldset><label class="field">我的预测依据<textarea data-bind="taskDraft.prediction" maxlength="1200" placeholder="例如：我想先代入前两步，看看是否回到原来的点。">${h(S.taskDraft.prediction)}</textarea></label><div class="actions">${button('next','保存预测并运行实验','btn')}</div>`;
    if(st===3){const r=getRun(S.runId);body=`<h2 class="lesson-title">先观察一条真实计算轨迹</h2><p class="small muted">参考计算 · 不是你的独立作答。选择步骤可查看该步的残差和导数。</p>${r?runView(r,true):'<p>运行尚未生成。</p>'}<div class="actions">${button('observe','我已观察这条轨迹','btn')}${button('open-experiment','在实验中心查看','btn secondary')}</div>`;}
    if(st===4)body=`<h2 class="lesson-title">现在，这条轨迹支持什么？</h2><fieldset class="choices" style="border:0;padding:0"><legend class="sr-only">可支持的主张</legend>${radio('claim','local','支持 x₀=1 时出现周期，不能推广到所有初值',S.claim)}${radio('claim','universal','支持这个方程从任意初值都不收敛',S.claim)}${radio('claim','residual','只要步差小，就证明根误差小',S.claim)}</fieldset><label class="field">用你自己的话说明依据<textarea data-bind="judgment" maxlength="1500" placeholder="把你观察到的点、可确认的步骤和结论范围分开。">${h(S.judgment)}</textarea></label><div class="actions">${button('judge','记录判断并查看反馈','btn')}</div>${S.feedback?`<div class="callout ${S.claim==='local'?'':'warn'}"><strong>规则化示例反馈 · 未调用模型</strong><p>${S.claim==='local'?'你选中的范围与该运行一致：1→0→1 可直接复算。请再比较另一个初值。':S.claim==='universal'?'这个初值的周期现象不能证明所有初值都失败。保留你算对的步骤，收窄结论，再试 x₀=−2。':'步差、残差、根误差是不同量。这条运行没有出现步差小；即使出现，也需要另外的误差依据。'}</p></div><div class="actions">${button('next','做一次对照并修订','btn')}</div>`:''}`;
    if(st===5){const r=getRun(S.reviseId);body=`<h2 class="lesson-title">只改变初值，试试 x₀ = −2</h2><p class="lesson-copy">方程保持不变。对照运行仅改变初值，检查“任意初值都不收敛”是否仍能成立。</p>${button('revise-run',r?'重新查看对照运行':'运行 x₀ = −2','btn secondary')}${r?`${runView(r,true)}<div class="comparison">第一条运行：x₀=1，周期 1↔0。<br>当前运行：x₀=−2，最终残差 ${fmt(r.rows.at(-1).residual)}。这是有限精度计算观察，不是任意初值的收敛证明。</div>`:''}<label class="field">我的修订<textarea data-bind="taskDraft.revised" maxlength="1500" placeholder="我原先认为……现在这两条运行只支持……">${h(S.taskDraft.revised)}</textarea></label><div class="actions">${button('next','保存修订，进入独立检验','btn')}</div>`;}
    if(st===6)body=`<h2 class="lesson-title">换一道题，只检查你自己的第一步</h2><span class="tag ${S.probe.help?'warn':''}">${S.probe.help?'已使用参考帮助':'独立模式 · 提交前不提供提示'}</span><div class="formula-box">f(x) = x² − 2，x₀ = 1<br>请填写一次 Newton 更新后的 x₁。</div><label class="field">我的 x₁<input data-bind="probe.answer" inputmode="decimal" value="${h(S.probe.answer)}" placeholder="输入数值"><small>本原型仅对这一数值候选检查，不能评价完整解题能力。</small></label><div class="actions">${button('probe-submit','核对我的第一步','btn')}${button('probe-help','查看参考（标记借助帮助）','btn secondary')}</div>${S.probe.help?'<div class="callout neutral">参考：x₁ = 1 − (1²−2)/(2×1) = 1.5。此后的完成记录保留“借助帮助”，刷新不会改回独立。</div>':''}${S.probe.submitted?`<div class="callout ${S.probe.passed?'':'warn'}" role="status">${S.probe.passed?(S.probe.help?'这个数值候选匹配参考计算；记录为借助帮助完成。':'这个数值候选核对通过；记录为本题第一步独立完成。'):'候选与参考第一步不同。你的输入已保留，可以修改后再次尝试。'}</div>${S.probe.passed?`<div class="actions">${button('next','回看这次学习','btn')}</div>`:''}`:''}`;
    if(st===7)body=`<div class="finish-mark" aria-hidden="true">✓</div><h2 class="lesson-title">把这次修订留下来</h2><p class="lesson-copy">你经历了条件、预测、周期观察和初值对照。独立题只核对了一次数值更新，不表示已经掌握 Newton 的全部收敛理论。</p><div class="callout"><strong>${S.probe.help?'参考帮助下完成数值题':'独立数值候选核对通过'}</strong><p>你的修订：${h(S.taskDraft.revised)}</p></div><div class="actions">${link('records','查看本次学习记录','btn')}${button('go-gs','迁移到 Gauss–Seidel','btn secondary')}</div>`;
    return heading('一项连续的数学任务','Newton：从局部计算到收敛判断','当前阶段：'+steps[st]+'。过程草稿、计算版本和帮助状态随任务保留。')+`<ol class="stepbar" aria-label="学习进程">${steps.map((label,i)=>`<li><button data-stage="${i}" ${i>S.unlocked?'disabled':''} ${i===st?'aria-current="step"':''}><span class="step-index">${i+1}</span>${label}</button></li>`).join('')}</ol><div class="workspace"><section class="panel" aria-label="当前学习步骤">${body}${error?`<p class="error" role="alert">${h(error)}</p>`:''}${st>0?`<div class="rule">${button('previous','返回上一阶段','btn quiet')}</div>`:''}</section>${ledger()}</div>`;
  }
  function plot(r){
    const w=640,hh=235,pad=36,rows=r.rows;let path='',points='';
    if(r.domain==='newton'){
      const values=rows.map(v=>v.x);const lo=Math.min(...values)-.7,hi=Math.max(...values)+.7;const fn=r.parameters.function==='sqrt2'?x=>x*x-2:x=>x*x*x-2*x+2;const samples=Array.from({length:121},(_,i)=>({x:lo+(hi-lo)*i/120})).map(p=>({...p,y:fn(p.x)}));const ymin=Math.min(-1,...samples.map(p=>p.y)),ymax=Math.max(1,...samples.map(p=>p.y));const X=x=>pad+(x-lo)/(hi-lo||1)*(w-2*pad),Y=y=>hh-pad-(y-ymin)/(ymax-ymin||1)*(hh-2*pad);path=samples.map((v,i)=>(i?'L':'M')+X(v.x).toFixed(2)+','+Y(v.y).toFixed(2)).join(' ');points=rows.map((v,i)=>`<circle class="${i===S.step?'point':''}" cx="${X(v.x)}" cy="${Y(0)}" r="${i===S.step?6:3}" fill="var(--dai)"/><text x="${X(v.x)+7}" y="${Y(0)-10-i%2*13}">${i===S.step?'选中 k='+i:''}</text>`).join('');return `<svg class="plot" viewBox="0 0 ${w} ${hh}" role="img" aria-label="函数曲线与 Newton 轨迹中的横坐标"><line class="axis" x1="${pad}" x2="${w-pad}" y1="${Y(0)}" y2="${Y(0)}"/><path class="curve" d="${path}"/>${points}<text x="${pad}" y="20">函数曲线 / 选中步骤标在横轴</text><text x="${pad}" y="${hh-9}">${fmt(lo,3)}</text><text x="${w-pad-20}" y="${hh-9}">${fmt(hi,3)}</text></svg>`;
    }
    const values=rows.map(v=>r.domain==='gs'?v.residual:v.partial),max=Math.max(1e-12,...values),X=i=>pad+i/Math.max(1,rows.length-1)*(w-2*pad),Y=v=>hh-pad-v/max*(hh-2*pad);path=values.map((v,i)=>(i?'L':'M')+X(i)+','+Y(v)).join(' ');const i=Math.min(S.step,rows.length-1);return `<svg class="plot" viewBox="0 0 ${w} ${hh}" role="img" aria-label="${r.domain==='gs'?'残差随迭代步变化':'求积加权和逐项变化'}"><line class="axis" x1="${pad}" x2="${w-pad}" y1="${hh-pad}" y2="${hh-pad}"/><path class="trajectory" d="${path}"/><circle class="point" cx="${X(i)}" cy="${Y(values[i])}" r="6"/><text x="${pad}" y="20">${r.domain==='gs'?'残差 ∞ 范数（线性坐标）':'加权求积和（最后一项才是完整近似）'}</text><text x="${pad}" y="${hh-10}">k = 0</text><text x="${w-pad-45}" y="${hh-10}">k = ${rows.length-1}</text></svg>`;
  }
  function runView(r,compact=false){const gs=r.domain==='gs',integration=r.domain==='integration';return `${plot(r)}<div class="run-meta"><span class="tag ${r.status==='cycle'||r.status==='derivative_zero'?'warn':''}">${statuses[r.status]}</span><span>${h(r.id)} · v${r.version}</span><span class="mono">${r.input_hash}</span><span>本地计算快照</span></div>${integration?`<div class="callout neutral">完整求积：${fmt(r.approximation,10)}；解析积分的浮点参考：${fmt(r.reference,10)}。<br>参考差：${fmt(Math.abs(r.approximation-r.reference))}，不称为一般严格误差界。</div>`:''}<div class="table-scroll"><table><caption>${compact?'选择行查看当前步骤；运行本身不会改变':'只讨论当前保存快照；选行后小珞引用同步更新'}</caption><thead><tr><th>步骤</th><th>${gs?'x₁':'x'}</th><th>${gs?'x₂':integration?'f(x)':'f(x)'}</th><th>${integration?'权重':'残差'}</th><th>${integration?'加权和':'步差'}</th></tr></thead><tbody>${r.rows.map((v,i)=>`<tr class="${i===S.step?'selected':''}"><td><button data-step="${i}" data-run="${r.id}" aria-label="选择步骤 ${i}">k=${i}</button></td><td class="mono">${fmt(v.x)}</td><td class="mono">${fmt(gs?v.y:v.fx)}</td><td class="mono">${fmt(integration?v.weight:v.residual)}</td><td class="mono">${fmt(integration?v.partial:v.delta)}</td></tr>`).join('')}</tbody></table></div>`;}
  function assistant(r=contextRun()){
    const row=r?.rows[Math.min(S.step,r.rows.length-1)];const block=locked();return `<aside class="assistant" aria-label="小珞上下文侧栏"><div class="assistant-head"><img src="assets/xiaoluo.png" alt="小珞形象"><div><h3>小珞 · 跟着这一步</h3><p class="small muted">规则化演示 · 未调用模型</p></div></div><div class="context-chip">${r?`${h(names[r.domain])} · ${h(r.id)} / v${r.version}<br>选中 k=${row?.k??0} · 摘要 ${r.input_hash}<br>参数与快照绑定；草稿修改不会改写这条记录。`:h(contextLabel())}</div>${block?`<div class="callout warn">独立检验仍在进行。查看提示会将本次尝试标记为借助帮助。</div>${button('probe-help','结束独立模式并查看参考','btn secondary')}`:`<div class="chat-message">${r?explain(r,row):'把条件、你的主张和计算证据放在一起。先从一项任务开始，或者选中实验中的一步。'}</div>${S.chat.filter(x=>(x.contextId===contextKey(r)||!x.contextId&&r&&x.runId===r.id)&&x.step===S.step).slice(-2).map(x=>`<div class="chat-message ${x.role==='student'?'student':''}">${h(x.text)}</div>`).join('')}<div class="quick-questions">${button('ask-scope','这一步能支持什么结论？','')}${button('ask-revise','下一步怎样做对照？','')}</div><label class="field">围绕当前来源提问<textarea data-bind="question" maxlength="1000" placeholder="这里只演示问题与来源一起保留。">${h(S.question)}</textarea></label>${button('ask','保存问题草稿并看示例','btn secondary')}`}<div class="actions">${r?button('dialogue-from-source','带此引用进入完整对话','btn secondary'):link('chat','打开自由对话','text-link')}</div><p class="small muted" style="margin-top:16px">正式产品应继续使用服务端规范引用与帮助回执。此处摘要只是原型标识。</p></aside>`;
  }
  function explain(r,row){if(!row)return '该记录没有可用步骤。';if(r.domain==='newton')return `当前 x${row.k}=${fmt(row.x)}，f(x)=${fmt(row.fx)}，f′(x)=${fmt(row.derivative)}。${r.status==='cycle'?'这条运行出现了重复轨迹，不能把该初值的周期推广为任意初值都失败。':'有限轨迹提供了计算观察，局部收敛的理论条件仍须另行核对。'}`;if(r.domain==='gs')return `第 ${row.k} 轮的向量是 [${fmt(row.x)}, ${fmt(row.y)}]，残差 ∞ 范数为 ${fmt(row.residual)}。第二个分量使用本轮更新的第一个分量；残差下降不单独证明任意矩阵下都收敛。`;return `节点 ${row.k}：x=${fmt(row.x)}，权重为 ${row.weight}。加权部分和 ${fmt(row.partial)} 还不是剩余误差。只有最后一个节点的加权和对应完整求积。`;}
  function fields(){const d=S.drafts[S.domain];if(S.domain==='newton')return `<label class="field wide">教学方程<select data-param="function"><option value="cycle" ${d.function==='cycle'?'selected':''}>x³ − 2x + 2（初值与周期）</option><option value="sqrt2" ${d.function==='sqrt2'?'selected':''}>x² − 2（平方根）</option></select></label><label class="field">初值 x₀<input data-param="x0" inputmode="decimal" value="${h(d.x0)}"></label><label class="field">最多步数<input data-param="limit" inputmode="numeric" value="${h(d.limit)}"></label><label class="field">残差阈值<input data-param="tolerance" inputmode="decimal" value="${h(d.tolerance)}"></label>`;if(S.domain==='gs')return `<label class="field wide">矩阵 A（按行输入 4 个数）<textarea data-param="matrix" style="min-height:65px">${h(d.matrix)}</textarea></label><label class="field">右端项 b<input data-param="rhs" value="${h(d.rhs)}"></label><label class="field">初值向量<input data-param="initial" value="${h(d.initial)}"></label><label class="field">最多轮数<input data-param="limit" inputmode="numeric" value="${h(d.limit)}"></label>`;return `<label class="field">方法<select data-param="method"><option value="simpson" ${d.method==='simpson'?'selected':''}>复合 Simpson</option><option value="trapezoid" ${d.method==='trapezoid'?'selected':''}>复合梯形</option></select></label><label class="field">左端点<input data-param="left" inputmode="decimal" value="${h(d.left)}"></label><label class="field">右端点<input data-param="right" inputmode="decimal" value="${h(d.right)}"></label><label class="field">子区间数<input data-param="intervals" inputmode="numeric" value="${h(d.intervals)}"></label>`;}
  function experiment(){const r=activeRun(),same=S.runs.filter(x=>x.domain===S.domain),compare=getRun(S.compare);return heading('数学实验中心','看见轨迹，也说明它的范围。','参数可以探索；对话始终绑定当前选中的计算版本。切换布局不会清空你的问题。')+`<div class="exp-toolbar"><div class="segmented" aria-label="实验领域">${Object.entries(names).map(([key,name])=>button('domain-'+key,name,'',`aria-pressed="${S.domain===key}"`)).join('')}</div><div class="segmented" aria-label="工作区布局">${button('layout-A','A · Chat 主导','',`aria-pressed="${S.layout==='A'}"`)}${button('layout-B','B · 实验主导','',`aria-pressed="${S.layout==='B'}"`)}</div></div><div class="exp-grid ${S.layout==='A'?'chat-first':''}"><section class="experiment-main"><div class="panel"><div class="section-head"><h2>${names[S.domain]}</h2><span class="tag neutral">参数草稿</span></div><p class="small muted">${S.domain==='integration'?'固定被积函数 exp(x)，不解析任意代码。':'修改后运行生成新快照，旧轨迹保持不变。'}</p><form id="experiment-form"><div class="params">${fields()}</div><label class="field">运行前的预测<textarea data-bind="prediction" maxlength="1200" placeholder="我预计会发生什么？依据是什么？">${h(S.prediction)}</textarea></label><button class="btn" type="submit" ${locked()?'disabled':''}>运行并保存演示快照</button>${locked()?'<p class="error">独立检验尚未结束；使用实验帮助前请明确标记借助帮助。</p>':''}${error?`<p class="error" role="alert">${h(error)}</p>`:''}</form>${r?`<div class="rule"><p class="formula">${h(r.expression)}</p>${runView(r)}<label class="field">与同领域运行对照<select id="compare"><option value="">选择另一次运行</option>${same.filter(x=>x.id!==r.id).map(x=>`<option value="${x.id}" ${S.compare===x.id?'selected':''}>v${x.version} · ${h(x.id)}</option>`).join('')}</select></label>${compare?`<div class="comparison"><strong>当前 v${r.version} ↔ 对照 v${compare.version}</strong><p>当前：${h(JSON.stringify(r.parameters))}<br>对照：${h(JSON.stringify(compare.parameters))}</p><p>${statuses[r.status]} ↔ ${statuses[compare.status]}。仅比较这些指定参数下的结果。</p></div>`:''}<div class="history-list" aria-label="运行历史">${same.map(x=>button('restore-'+x.id,`v${x.version} · ${statuses[x.status]}`,'',`aria-pressed="${x.id===r.id}"`)).join('')}</div><label class="field">这次观察后，我怎样修订？<textarea data-bind="revised" maxlength="1500" placeholder="记录可以支持的结论，以及仍不能确定的部分。">${h(S.revised)}</textarea></label>${button('save-conclusion','保存本次结论到学习记录','btn secondary')}</div>`:'<div class="empty rule"><h3>先保存你的预测，再运行一次。</h3><p>这里会出现真实浏览器计算的轨迹与逐步引用。</p></div>'}</div></section>${assistant(r)}</div><p class="statusline">${S.layout==='A'?'A：适合围绕主张展开长对话，实验保持在旁；窄屏按顺序阅读。':'B：适合调参、逐步观察与对照，助教解释选中的步骤。推荐作为实验中心默认。'}</p>`;}
  function records(){const items=S.records.filter(r=>(S.filter==='all'||S.filter==='review'&&(['error','reading'].includes(r.type)||S.review.includes(r.id))||S.filter==='probe'&&r.type==='probe')&&(!S.search||(r.title+r.concept+r.text).includes(S.search)));const selected=items.find(r=>r.id===S.selectedRecord)||items[0];if(S.selectedRecord!==(selected?.id||null)){S.selectedRecord=selected?.id||null;save();}return heading('我的学习记录','不只记住做过什么，也知道下一步。','按知识点回看阅读、实验、修订和错误；每项记录保留来源与帮助状态。')+`<div class="exp-toolbar"><div class="segmented" aria-label="记录筛选">${[['all','全部过程'],['review','待复习'],['probe','独立检验']].map(([key,label])=>button('filter-'+key,label,'',`aria-pressed="${S.filter===key}"`)).join('')}</div><form id="search-form" style="display:flex;gap:8px;max-width:100%"><label class="sr-only" for="record-search">搜索知识点或记录</label><input id="record-search" placeholder="搜索知识点或记录" value="${h(S.search)}" style="max-width:240px"><button class="btn secondary" type="submit">查找</button></form></div><div class="records-layout"><section aria-label="知识点过程时间线">${items.length?items.map(r=>`<button class="record-item ${r.id===selected?.id?'selected':''}" data-record="${h(r.id)}"><span class="record-kind">${{error:'?',reading:'文',note:'记',experiment:'ƒ',revision:'改',probe:'✓'}[r.type]||'记'}</span><span><span class="small muted">${h(r.concept)}</span><h3>${h(r.title)}</h3><p>${h(r.source)}</p><span class="tag ${r.type==='error'?'warn':''}">${h(r.help)}</span></span></button>`).join(''):`<div class="empty"><h2>这里还没有匹配的学习记录。</h2><p>可开始一项任务，或清除筛选继续查看。</p><div class="actions" style="justify-content:center">${link('learn','开始 Newton 任务','btn')}${button('clear-filter','清除筛选','btn secondary')}</div></div>`}</section>${selected?`<aside class="record-detail" aria-label="记录来源与下一步"><span class="eyebrow">${h(selected.concept)}</span><h2>${h(selected.title)}</h2><p>${h(selected.text)}</p><div class="rule"><h3>依据与来源</h3><p>${h(selected.evidence)}</p><p class="small muted">${h(selected.source)}</p><span class="tag ${selected.help.includes('帮助')?'warn':''}">${h(selected.help)}</span></div>${button('reopen-'+selected.id,selected.runId?'恢复这次计算并讨论':'回到相关学习任务','btn')}${button('review-'+selected.id,S.review.includes(selected.id)?'已加入本地复习':'加入本地复习','btn secondary')}</aside>`:''}</div>`;}

  // Ordinary conversation owns its messages. Experiment references are opt-in snapshots.
  function newDialogue(draft='',reference=null){
    const previous=S.dialogue.sessions.find(x=>x.id===S.dialogue.selected);if(previous)previous.draft=S.dialogue.draft;
    const session={id:'dialogue-'+Date.now()+'-'+S.dialogue.sessions.length,title:'新的对话',messages:[],reference};
    S.dialogue.sessions.unshift(session);S.dialogue.selected=session.id;S.dialogue.draft=draft;save();return session;
  }
  function currentDialogue(){return S.dialogue.sessions.find(x=>x.id===S.dialogue.selected)||newDialogue(S.dialogue.draft);}
  function dialogueRef(r){return r?{runId:r.id,version:r.version,hash:r.input_hash,step:r.id===S.selectedRun?S.step:0,label:names[r.domain]}:null;}
  function refLabel(ref){if(ref?.kind==='material')return `${ref.title} / v${ref.version} · ${ref.paragraph==null?'整份材料':'第 '+(ref.paragraph+1)+' 段'} · ${ref.hash}`;return ref?`${ref.label} · ${ref.runId} / v${ref.version} · k=${ref.step} · ${ref.hash}`:'';}
  function homeDialogue(){return `<section class="home-dialogue" aria-label="直接和小珞对话"><div><h2>有问题，直接问小珞。</h2><p>聊一个概念、检查一段推导，或从你还没想清楚的地方开始。</p></div><form id="home-dialogue-form"><label class="sr-only" for="home-question">想和小珞聊什么？</label><textarea id="home-question" data-bind="homeQuestion" maxlength="3000" placeholder="例如：连续和可导到底有什么区别？">${h(S.homeQuestion)}</textarea><div class="actions"><button class="btn" type="submit">开始对话</button>${link('chat','直接进入对话','text-link')}${link('chat?materials=1','选材料一起读','text-link')}<span class="small muted">模型未连接 · 原型演示</span></div></form></section>`;}

  function freeDialogue(){
    const session=currentDialogue(),block=locked();
    return `<div class="dialogue-page">${heading('小珞 · 自由对话','从你想聊的问题开始。','可以直接聊，也可以带一段材料来读；实验和学习任务由你选择。')}${materialImport()}<div class="${getDialogueMaterial(session)?'dialogue-with-material':''}">${materialReader(session)}<div class="dialogue-main"><div class="dialogue-toolbar"><span class="tag neutral">${session.reference?'已手动添加引用':'普通对话 · 无学习引用'}</span>${button('dialogue-new','新对话','btn secondary')}<details class="dialogue-history"><summary>最近对话（${S.dialogue.sessions.length}）</summary><div>${S.dialogue.sessions.map(x=>button('dialogue-open-'+x.id,h(x.title),'',`aria-pressed="${x.id===session.id}"`)).join('')}</div></details></div><section class="dialogue-thread" aria-label="对话消息">${block?'<div class="callout warn">当前有一项独立检验尚未结束。对话草稿可以保留；查看示例或获得帮助前，请先将该次尝试标记为借助帮助。</div>':session.messages.length?session.messages.map((m,i)=>`<article class="dialogue-message ${m.role}" aria-label="${m.role==='student'?'我的消息':m.role==='assistant'?'小珞预写示例':'原型状态'}"><div class="small muted">${m.role==='student'?(m.example?'示例提问':'我'):m.role==='assistant'?'小珞 · 预写教学示例，非模型生成':'原型状态 · 未调用模型'}</div><p>${h(m.text)}</p>${m.reference?`<p class="message-source">此条消息的引用：${h(refLabel(m.reference))}</p>${m.reference.quote?`<blockquote class="material-reference-quote">${h(m.reference.quote)}</blockquote>`:''}${m.reference.kind==='material'?button('dialogue-return-'+i,'回看这条消息的原文','material-return'):''}`:''}</article>`).join(''):`<div class="dialogue-empty"><img src="assets/xiaoluo.png" alt="小珞"><h2>不用准备好问题，也可以开口。</h2><p>解释一个概念，检查一段推导，或一起读懂讲义中的一句话。</p><div class="dialogue-topics">${button('dialogue-topic-concept','聊聊连续和可导','btn secondary')}${button('dialogue-topic-proof','一起检查证明思路','btn secondary')}${button('dialogue-topic-study','讨论怎么学，不安排练习','btn secondary')}</div>${button('dialogue-example','查看一段纯对话示例','btn quiet')}${button('dialogue-material-example','体验材料伴读示例','btn quiet')}</div>`}</section>${block?`<div class="actions">${button('dialogue-help','使用对话帮助（标记借助帮助）','btn secondary')}${link('learn','返回独立检验','text-link')}</div>`:''}<form class="dialogue-composer" id="dialogue-form">${session.reference?`<div class="dialogue-reference"><span>${h(refLabel(session.reference))}</span>${button('dialogue-detach','移除引用','btn quiet')}</div><p class="small muted">当前提问使用此引用；换引用时草稿保留，请核对指代。已发送消息保留各自来源。</p>${session.reference.quote?`<blockquote class="material-reference-quote">${h(session.reference.quote)}</blockquote>`:''}`:''}<label class="sr-only" for="dialogue-message">给小珞的消息</label><textarea id="dialogue-message" maxlength="3000" placeholder="说说你的问题、想法，或贴一段推导。">${h(S.dialogue.draft)}</textarea><div class="dialogue-compose-actions"><details><summary>添加实验引用（可选）</summary>${S.runs.length?`<label class="field">选择已保存的实验<select id="dialogue-source"><option value="">选择后附加到当前对话</option>${S.runs.map(r=>`<option value="${h(r.id)}">${h(names[r.domain])} · ${h(r.id)} / v${r.version}</option>`).join('')}</select></label>`:'<p class="small muted">还没有实验快照。可以继续普通对话，需要时再去实验中心保存。</p>'}<p class="small muted">只携带你选择的来源；添加引用不会启动实验或学习任务。</p></details><button class="btn" type="submit" ${block?'disabled':''}>发送消息</button></div><p class="small muted">原型仅保存消息、草稿与引用，任意提问不会生成模型回答。示例对话均为预写内容。</p>${error?`<p class="error" role="alert">${h(error)}</p>`:''}</form></div></div></div>`;
  }
  function materialImport(){return `<details class="material-import" ${new URLSearchParams(location.hash.split('?')[1]||'').get('materials')==='1'?'open':''}><summary>带一份材料来聊：粘贴、导入或选择</summary><p class="small muted">支持 UTF-8 的 .txt / .md（200KB、20000 字符以内）。内容只保存在本浏览器原型空间；此处不解析 PDF。</p><label class="field">导入文本文件<input id="material-file" type="file" accept=".txt,.md,text/plain,text/markdown"></label><form id="material-paste"><label class="field">材料名称<input id="material-title" maxlength="100" value="${h(S.dialogue.materialTitle)}" placeholder="例如：我的数学分析讲义"></label><label class="field">材料正文<textarea id="material-text" maxlength="20000" placeholder="粘贴想一起阅读的原文，保留段落。">${h(S.dialogue.materialText)}</textarea></label><button class="btn secondary" type="submit">保存材料并开始伴读</button></form><div class="material-tools">${button('dialogue-material-example','体验材料伴读示例','btn quiet')}</div><div class="material-library">${S.dialogue.materials.map(m=>button('dialogue-material-open-'+m.id,h(m.title)+' / v'+m.version,'btn secondary')).join('')}</div></details>`;}
  function getDialogueMaterial(session){return session.reference?.kind==='material'?S.dialogue.materials.find(m=>m.id===session.reference.materialId):null;}
  function materialReader(session){
    const m=getDialogueMaterial(session);if(!m)return '';
    return `<aside class="material-reader" aria-label="材料原文"><span class="eyebrow">当前材料 · ${h(m.origin)}</span><h2>${h(m.title)}</h2><p class="material-meta">版本 v${m.version} · 原型摘要 ${m.hash}<br>${m.example?'原型编写的示例讲义，非教材原文，未独立审核。':'用户提供的文本，来源与数学内容未经审核。'}</p>${locked()?'<p class="callout warn">独立检验进行中；阅读额外材料前，请先标记借助帮助。</p>':`<div id="material-content">${m.paragraphs.map((text,i)=>`<section class="material-paragraph" id="material-paragraph-${i}"><span class="small muted">第 ${i+1} 段</span><p data-material-para="${i}">${h(text)}</p>${button('dialogue-quote-'+i,'引用第 '+(i+1)+' 段提问','btn secondary')}</section>`).join('')}</div>${button('dialogue-quote-selection','引用我选中的文字','btn secondary')}<p class="small muted">鼠标选中同一段内的文字，或用段落按钮引用；引用固定到这份文本版本。</p>${session.reference.quote?`<div class="quote-preview">当前选段：${h(session.reference.quote)}</div>`:''}`}</aside>`;
  }
  function addMaterial(title,text,origin,example=false){
    if(!title.trim()||!text.trim())throw Error('请补充材料名称和正文，输入会保留。');
    if(text.length>20000)throw Error('正文超过 20000 字符，请截取需要讨论的部分。');
    const name=title.trim().slice(0,100);
    const m={id:'material-'+Date.now()+'-'+S.dialogue.materials.length,title:name,text,
      paragraphs:text.split(/\n\s*\n/).filter(x=>x.trim()),origin,example,
      version:S.dialogue.materials.filter(x=>x.title===name).length+1,hash:M.hash({text})};
    S.dialogue.materials.push(m);save();return m;
  }
  function materialRef(m,paragraph=null,start=0,end=null){
    const text=paragraph==null?null:m.paragraphs[paragraph];
    return {kind:'material',materialId:m.id,title:m.title,version:m.version,hash:m.hash,paragraph,
      start:paragraph==null?null:start,end:paragraph==null?null:end??text.length,quote:paragraph==null?null:text.slice(start,end??text.length)};
  }
  function materialAction(action){
    if(action==='dialogue-material-example'){
      if(locked()){error='独立检验尚未结束；先明确是否使用帮助。';render();return true;}
      let m=S.dialogue.materials.find(x=>x.example);
      if(!m)m=addMaterial('连续与可导：读一段证明',[
        '若 f 在 a 处可导，则差商 [f(a+h)−f(a)]/h 在 h→0 时有有限极限 f′(a)。这里 h≠0，且 a 附近的函数值需要有定义。',
        '对 h≠0，可写成 f(a+h)−f(a)=h·[f(a+h)−f(a)]/h。第一个因子趋于 0，第二个因子趋于有限的 f′(a)，故函数增量趋于 0，得到 f 在 a 处连续。',
        '反过来，连续不一定可导。f(x)=|x| 在 0 连续，但差商的左右极限分别为 −1 和 1，在 0 不可导。'
      ].join('\n\n'),'原型示例讲义',true);
      closeMaterialPicker();const ref=materialRef(m,1),session=newDialogue('',ref);session.title='示例伴读：可导为何连续';
      session.messages=[{role:'student',example:true,text:'这一段为什么能说乘积趋于 0？是不是只要一个因子趋于 0 就行？',reference:structuredClone(ref)},
        {role:'assistant',example:true,text:'这里还用到了第二个因子趋于有限值：差商趋于 f′(a)，因此在充分小的去心邻域内有界。h 趋于 0，乘上这个有界量，函数增量才趋于 0。若另一个因子无界，就不能只凭第一个因子趋于 0 下结论，例如 h·(1/h)=1。',reference:structuredClone(ref)}];save();render(true);return true;
    }
    if(action.startsWith('dialogue-material-open-')){const m=S.dialogue.materials.find(x=>x.id===action.slice(23));if(m){currentDialogue().reference=materialRef(m);save();closeMaterialPicker();render(true);}return true;}
    if(action.startsWith('dialogue-quote-')){
      if(locked())return true;const session=currentDialogue(),m=getDialogueMaterial(session);if(!m)return true;
      if(action==='dialogue-quote-selection'){
        if(!materialSelection||materialSelection.materialId!==m.id){error='请先在当前材料的同一段中选中文字，或使用段落引用按钮。';render();return true;}
        session.reference=materialRef(m,materialSelection.paragraph,materialSelection.start,materialSelection.end);
      }else{const i=Number(action.slice(15));if(!Number.isInteger(i)||!m.paragraphs[i])return true;session.reference=materialRef(m,i);}
      save();render();document.querySelector('#dialogue-message')?.focus();return true;
    }
    if(action.startsWith('dialogue-return-')){const ref=currentDialogue().messages[Number(action.slice(16))]?.reference;
      const m=S.dialogue.materials.find(x=>x.id===ref?.materialId);if(m){currentDialogue().reference=structuredClone(ref);save();render();document.querySelector('#material-paragraph-'+(ref.paragraph??0))?.scrollIntoView({block:'center'});}return true;}
    return false;
  }
  function closeMaterialPicker(){if(route==='chat')history.replaceState(null,'','#chat');}
  function bindMaterial(){
    document.querySelector('#material-title')?.addEventListener('input',e=>{S.dialogue.materialTitle=e.target.value;save();});
    document.querySelector('#material-text')?.addEventListener('input',e=>{S.dialogue.materialText=e.target.value;save();});
    document.querySelector('#material-paste')?.addEventListener('submit',e=>{e.preventDefault();try{const m=addMaterial(S.dialogue.materialTitle,S.dialogue.materialText,'粘贴文本');currentDialogue().reference=materialRef(m);error='';save();closeMaterialPicker();render(true);}catch(err){error=err.message;render();}});
    document.querySelector('#material-file')?.addEventListener('change',async e=>{
      const file=e.target.files?.[0];if(!file)return;const sessionId=currentDialogue().id;
      try{if(!/\.(txt|md)$/i.test(file.name)||file.size>200*1024)throw Error('请选择 200KB 内的 UTF-8 .txt 或 .md 文件。');
        const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());
        const m=addMaterial(file.name,text,'导入文本文件');
        const session=S.dialogue.sessions.find(x=>x.id===sessionId);if(session)session.reference=materialRef(m);
        error='';save();if(route==='chat'&&S.dialogue.selected===sessionId){closeMaterialPicker();render(true);}
      }catch(err){error=err instanceof TypeError?'文件不是有效 UTF-8 文本；请转换编码后重试。':err.message;if(route==='chat'&&S.dialogue.selected===sessionId)render();}
    });
  }
  document.addEventListener('selectionchange',()=>{
    const selection=window.getSelection();if(!selection||selection.isCollapsed)return;
    const p=selection.anchorNode?.parentElement?.closest('[data-material-para]');
    if(!p||!p.contains(selection.focusNode)||route!=='chat')return;
    const range=selection.getRangeAt(0),prefix=range.cloneRange();prefix.selectNodeContents(p);prefix.setEnd(range.startContainer,range.startOffset);
    const start=prefix.toString().length,quote=selection.toString(),m=getDialogueMaterial(currentDialogue()),paragraph=Number(p.dataset.materialPara);
    if(m&&quote&&m.paragraphs[paragraph].slice(start,start+quote.length)===quote)materialSelection={materialId:m.id,paragraph,start,end:start+quote.length};
  });
  function bindDialogue(){bindMaterial();
    document.querySelector('#home-dialogue-form')?.addEventListener('submit',e=>{e.preventDefault();newDialogue(S.homeQuestion.trim());location.hash='chat';});
    document.querySelector('#dialogue-message')?.addEventListener('input',e=>{S.dialogue.draft=e.target.value;save();});
    document.querySelector('#dialogue-form')?.addEventListener('submit',e=>{
      e.preventDefault();if(locked())return;const text=S.dialogue.draft.trim();
      if(!text){error='先写一句消息，草稿会留在这里。';render();document.querySelector('#dialogue-message')?.focus();return;}
      const session=currentDialogue();if(!session.messages.length)session.title=text.slice(0,24);
      session.messages.push({role:'student',text,reference:session.reference?structuredClone(session.reference):null},
        {role:'notice',text:'消息已保存在这段原型对话中，尚未生成模型回答。你可以继续提问或稍后回来。'});
      S.dialogue.draft='';save();render();announce('消息已保存在当前原型对话，未调用模型。');document.querySelector('#dialogue-message')?.focus();
    });
    document.querySelector('#dialogue-source')?.addEventListener('change',e=>{const r=getRun(e.target.value);if(r){currentDialogue().reference=dialogueRef(r);save();render();}});
  }
  function dialogueAction(action){
    if(!action.startsWith('dialogue-'))return false;if(materialAction(action))return true;
    if(action==='dialogue-from-source'){newDialogue('',dialogueRef(contextRun()));location.hash='chat';return true;}
    if(action==='dialogue-new'){newDialogue();closeMaterialPicker();render(true);return true;}
    if(action.startsWith('dialogue-open-')){const session=S.dialogue.sessions.find(x=>x.id===action.slice(14));if(session){currentDialogue().draft=S.dialogue.draft;S.dialogue.selected=session.id;S.dialogue.draft=session.draft||'';save();render(true);}return true;}
    if(action==='dialogue-detach'){currentDialogue().reference=null;save();render();return true;}
    if(action==='dialogue-help'){if(S.probe.active&&!S.probe.passed)S.probe.help=true;if(S.reviewAttempt?.active&&!S.reviewAttempt.passed)S.reviewAttempt.help=true;save();render();return true;}
    if(action.startsWith('dialogue-topic-')){const topics={concept:'连续和可导有什么区别？先用定义和反例解释。',proof:'我想检查一段证明。请先和我确认前提，再看推理是否充分。',study:'我想聊聊数值分析怎么学，暂时不安排练习或实验。'};S.dialogue.draft=topics[action.slice(15)]||'';save();render();document.querySelector('#dialogue-message')?.focus();return true;}
    if(action==='dialogue-example'){
      if(locked())return true;const session=newDialogue();session.title='示例：连续与可导';
      session.messages=[{role:'student',example:true,text:'连续就一定可导吗？我只想先理解概念。'},
        {role:'assistant',example:true,text:'不一定。以 f(x)=|x| 为例，它在 0 连续，但差商 |h|/h 在 h>0 时为 1，在 h<0 时为 −1，左右极限不同，所以在 0 不可导。连续要求函数值接近，可导还要求差商存在有限极限。'},
        {role:'student',example:true,text:'那可导一定连续吗？不用实验，直接证明。'},
        {role:'assistant',example:true,text:'一定。若 f 在 a 可导，则 [f(a+h)−f(a)]/h 在 h→0 时趋于有限的 f′(a)。对 h≠0，有 f(a+h)−f(a)=h·[f(a+h)−f(a)]/h，右侧趋于 0，因此 f(a+h)→f(a)，即在 a 连续。'}];save();render(true);return true;
    }
    return true;
  }

  function render(focus=false){document.querySelector('#app').innerHTML=shell(({home,chat:freeDialogue,learn,experiment,records}[route])());bind();if(focus){document.querySelector('h1')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
  function bind(){bindDialogue();document.querySelectorAll('[data-bind]').forEach(el=>el.addEventListener('input',()=>{const [a,b]=el.dataset.bind.split('.');if(b)S[a][b]=el.value;else S[a]=el.value;save();}));document.querySelectorAll('[data-param]').forEach(el=>el.addEventListener('input',()=>{S.drafts[S.domain][el.dataset.param]=el.value;save();}));document.querySelectorAll('input[name=predictionChoice],input[name=claim]').forEach(el=>el.addEventListener('change',()=>{S[el.name]=el.value;if(el.name==='claim')S.feedback=false;save();}));document.querySelector('#conditions')?.addEventListener('change',e=>{S.conditions=e.target.checked;save();});document.querySelector('#experiment-form')?.addEventListener('submit',e=>{e.preventDefault();if(locked())return;try{if(!S.prediction.trim())throw Error('先写下一句预测，运行后可以修订。');addRun(S.domain,S.drafts[S.domain]);error='';render();announce('已保存新的演示计算快照。');}catch(err){error=err.message;render();}});document.querySelector('#compare')?.addEventListener('change',e=>{S.compare=e.target.value;save();render();});document.querySelector('#search-form')?.addEventListener('submit',e=>{e.preventDefault();S.search=document.querySelector('#record-search').value;save();render();});document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>act(el.dataset.action)));document.querySelectorAll('[data-stage]').forEach(el=>el.addEventListener('click',()=>{const n=Number(el.dataset.stage);if(n<=S.unlocked){S.stage=n;error='';save();render(true);}}));document.querySelectorAll('[data-step]').forEach(el=>el.addEventListener('click',()=>{S.selectedRun=el.dataset.run;S.step=Number(el.dataset.step);save();render();announce('已选择步骤 '+S.step+'，上下文同步更新。');}));document.querySelectorAll('[data-record]').forEach(el=>el.addEventListener('click',()=>{S.selectedRecord=el.dataset.record;save();if(route==='records'){render();document.querySelector('.record-detail')?.scrollIntoView({block:'nearest',behavior:'auto'});}}));}
  function act(action){error='';if(dialogueAction(action))return;
    if(action==='review-help'||action==='probe-help'&&S.reviewAttempt?.active){if(!S.reviewAttempt.passed)S.reviewAttempt.help=true;save();document.querySelector('#tutor-dialog')?.close();render();return;}
    if(action==='review-submit'){const a=S.reviewAttempt;if(!a.answer.trim()||!Number.isFinite(Number(a.answer))){error='请输入有限数值；文字理由会保留。';render();return;}a.submitted=true;a.passed=Math.abs(Number(a.answer)-2)<=1e-10;if(a.passed)a.active=false;addRecord({type:'probe',concept:'残差与根误差',title:a.passed?'误差复习：新题数值匹配':'误差复习：新题待修订',text:'候选根误差：'+a.answer+'；我的理由：'+a.reason,evidence:'新题 g(x)=10^-8(x-2)，x=0；只核对数值，未评分文字理由。',source:'从 '+S.reviewOrigin+' 进入的新题 v1',reviewSourceId:S.reviewOrigin,help:a.help?'借助参考帮助':a.passed?'本题数值独立完成':'独立尝试，尚未通过',action:'learn'});save();render();return;}
    if(action==='review-exit'){if(S.reviewAttempt)S.reviewAttempt.active=false;S.reviewOrigin=null;save();render(true);return;}

    if(action==='next'){
      if(S.stage===1&&!S.conditions)error='先确认你将区分当前一步和整体结论。';
      else if(S.stage===2&&(!S.predictionChoice||!S.taskDraft.prediction.trim()))error='请选择预测，并写下你的依据。';
      else if(S.stage===4&&!S.feedback)error='先记录你的判断并查看本任务的示例反馈。';
      else if(S.stage===5&&(!S.reviseId||!S.taskDraft.revised.trim()))error='请先运行对照，并留下你修订后的主张。';
      else if(S.stage===6&&!S.probe.passed)error='请先核对自己的数值候选。';
      else{if(S.stage===2){S.taskPrediction=S.taskDraft.prediction;const r=addRun('newton',{function:'cycle',x0:1,limit:8,tolerance:1e-7},S.taskDraft.prediction);S.runId=r.id;S.step=0;}if(S.stage===5){S.probe.active=true;addRecord({type:'revision',concept:'Newton 的适用条件',title:'从周期现象修订整体主张',text:S.taskDraft.revised,evidence:'对照初值 1 与 −2，保存的两条运行可分别恢复。',source:'本原型任务 · '+S.runId+' / '+S.reviseId,help:'参考学习阶段',action:'learn',runId:S.reviseId});}next(Math.min(7,S.stage+1));return;}render();return;
    }
    if(action==='previous'){S.stage=Math.max(0,S.stage-1);save();render(true);return;}
    if(action==='observe'){S.observed=true;next(4);return;}
    if(action==='judge'){if(!S.claim||!S.judgment.trim()){error='请选择一项主张，并写下你自己的依据。';render();return;}S.feedback=true;save();render();return;}
    if(action==='revise-run'){if(!S.reviseId)S.reviseId=addRun('newton',{function:'cycle',x0:-2,limit:10,tolerance:1e-7},S.taskPrediction||S.taskDraft.prediction).id;S.selectedRun=S.reviseId;save();render();return;}
    if(action==='probe-help'){if(S.probe.passed){toast('该次已完成记录保持原帮助状态。');return;}S.probe.help=true;save();document.querySelector('#tutor-dialog')?.close();render();toast('本次尝试已标记借助帮助。');return;}
    if(action==='probe-submit'){const value=Number(S.probe.answer);if(!S.probe.answer.trim()||!Number.isFinite(value)){error='请输入一个有限数值，原输入已保留。';render();return;}S.probe.attempts++;S.probe.submitted=true;S.probe.passed=Math.abs(value-1.5)<=1e-10;addRecord({type:'probe',concept:'Newton 一步更新',title:S.probe.passed?'新题第一步：数值候选匹配':'新题第一步：待修订',text:'我的输入：'+S.probe.answer,evidence:'固定题 f(x)=x²−2，x₀=1。仅核对一个数值候选。',source:'本原型独立数值题 v1 · 尝试 '+S.probe.attempts,help:S.probe.help?'借助参考帮助':S.probe.passed?'本题第一步独立完成':'独立尝试，尚未通过',action:'learn'});if(S.probe.passed)S.unlocked=7;save();render();return;}
    if(action==='open-experiment'){S.selectedRun=S.runId;S.domain='newton';save();location.hash='experiment';return;}
    if(action.startsWith('go-')){S.domain=action.slice(3);const r=S.runs.filter(v=>v.domain===S.domain).at(-1);S.selectedRun=r?.id||null;S.step=0;save();if(route==='experiment')render();else location.hash='experiment';return;}
    if(action.startsWith('domain-')){S.domain=action.slice(7);S.selectedRun=S.runs.filter(v=>v.domain===S.domain).at(-1)?.id||null;S.step=0;save();render();return;}
    if(action.startsWith('layout-')){S.layout=action.slice(7);history.replaceState(null,'','#experiment?layout='+S.layout);save();render();return;}
    if(action.startsWith('restore-')){const r=getRun(action.slice(8));if(!r){toast('该原型运行已不存在，请重新运行。');return;}S.selectedRun=r.id;S.domain=r.domain;S.step=0;save();render();return;}
    if(action==='save-conclusion'){const r=activeRun();if(!r||!S.revised.trim()){error='请先保存一次运行，并写下本次结论。';render();return;}addRecord({type:'experiment',concept:names[r.domain],title:'实验后的判断与修订',text:S.revised,evidence:r.scope+'。预测：'+r.prediction,source:r.id+' / v'+r.version+' / '+r.input_hash,help:'参考计算与示例帮助',runId:r.id,action:'experiment'});toast('已保存到本原型的学习记录。');return;}
    if(action.startsWith('filter-')){S.filter=action.slice(7);save();render();return;}
    if(action==='clear-filter'){S.filter='all';S.search='';save();render();return;}
    if(action.startsWith('review-')){const id=action.slice(7);if(!S.review.includes(id))S.review.push(id);save();render();toast('已加入本原型的复习列表。');return;}
    if(action.startsWith('reopen-')){const record=S.records.find(r=>r.id===action.slice(7));if(!record)return;if(record.runId&&getRun(record.runId)){const r=getRun(record.runId);S.selectedRun=r.id;S.domain=r.domain;S.step=0;save();location.hash='experiment';}else if(record.action==='experiment'){S.domain=record.domain||'gs';S.selectedRun=S.runs.filter(r=>r.domain===S.domain).at(-1)?.id||null;save();location.hash='experiment';}else{if(record.type==='error'||record.reviewSourceId){S.reviewOrigin=record.reviewSourceId||record.id;if(S.reviewAttempt?.sourceId!==S.reviewOrigin)S.reviewAttempt={sourceId:S.reviewOrigin,active:true,answer:'',reason:'',help:false,passed:false,submitted:false};else S.reviewAttempt.active=!S.reviewAttempt.passed;}else{S.reviewOrigin=null;if(S.reviewAttempt)S.reviewAttempt.active=false;}S.unlocked=Math.max(S.unlocked,S.stage);save();location.hash='learn';}return;}
    if(action==='open-tutor'){if(route==='chat'){document.querySelector('#dialogue-message')?.focus();return;}const d=document.querySelector('#tutor-dialog');document.querySelector('#drawer-content').innerHTML=assistant();d.showModal();document.querySelectorAll('#drawer-content [data-action]').forEach(el=>el.addEventListener('click',()=>act(el.dataset.action)));document.querySelector('#drawer-content [data-bind=question]')?.addEventListener('input',e=>{S.question=e.target.value;save();});return;}
    if(action==='close-tutor'){document.querySelector('#tutor-dialog').close();return;}
    if(action.startsWith('ask')){if(locked()){toast('独立检验中，请先明确选择是否使用帮助。');return;}const r=contextRun();const question=action==='ask-scope'?'这一步能支持什么结论？':action==='ask-revise'?'下一步怎样做对照？':S.question.trim();if(!question){toast('先写一个围绕当前来源的问题。');return;}const reply=action==='ask-revise'?(r?.domain==='newton'?'保持方程不变，只改变初值。先写预测，再比较轨迹；不要把新一次成功当作全称证明。':'一次只改变一个参数，并保存新版本。先核对两条运行的差异，再修订主张。'):action==='ask-scope'&&r?explain(r,r.rows[Math.min(S.step,r.rows.length-1)]):'问题与当前来源已留在原型中。开放数学回答尚未生成；这里仅演示上下文携带，不把预写文本当成模型判断。';S.chat.push({role:'student',text:question,runId:r?.id||null,contextId:contextKey(r),step:S.step},{role:'assistant',text:reply,runId:r?.id||null,contextId:contextKey(r),step:S.step});save();const wasOpen=document.querySelector('#tutor-dialog').open;render();if(wasOpen)act('open-tutor');return;}
    if(action==='empty-records'){S.records=[];S.selectedRecord=null;save();location.hash='records';render();return;}
    if(action==='reset'){if(confirm('重置这套原型的演示记录和草稿？正式产品数据不会受影响。')){S=defaults();save();error='';if(location.hash==='#home')render();else location.hash='home';}return;}
  }
  document.querySelector('.skip').onclick=e=>{e.preventDefault();document.getElementById('main').focus();};
  window.addEventListener('hashchange',parseRoute);parseRoute();
})();
